              "caption": "St Mary’s twelfth-century Norman Priory Church standing inside the Roman outer-bailey walls of Portchester Castle, Hampshire (founded by Henry I c. 1133): Demonstrating how Norman stone castles and Romanesque churches fused military and spiritual authority side by side.",
              "author": "Norman Master Masons and Augustinian Monks",
              "date": "c. 1120s",
              "question_badge": "LOCAL FIELDWORK & MILITARY FORENSICS",
