        "curriculum_link": "KS3 Medieval Britain (1066–1509): Consolidating the Norman Conquest — evaluating military architecture, state terror, feudalism, and Domesday bureaucracy.",
        "hinge_question": "How did fewer than 10,000 Normans keep permanent control over two million hostile Anglo-Saxons when swords and battlefields alone could not be everywhere at once?",
        "hinge_guidance": "Strong answers connect three interlocking tools of control: rapid physical domination (over 500 motte-and-bailey castles built in 8–14 days, then stone keeps like Portchester), merciless deterrence (the 1069–70 Harrying of the North), and total economic dispossession recorded in the 1086 Domesday Book (Source D). Probe any pupil who focuses only on castles without explaining how stripping land from Anglo-Saxon thegns funded Norman knights.",
        "misconceptions": [
          {
            "misconception": "William the Conqueror immediately built giant stone castles with turrets across England in 1066.",
            "correction": "Stone keeps like Portchester Castle (Source E) took years to quarry and build; in 1066–1068 Normans threw up over 500 earth-and-timber motte-and-bailey forts like Hastings and Berkhamsted (Source B) in under two weeks."
          },
          {
            "misconception": "The 1086 Domesday Book was a population census counting every man, woman, and child in England.",
            "correction": "Commissioned at Gloucester in 1085 when King Cnut IV of Denmark threatened invasion, the Domesday Book (Source D) audited manors, ploughs, mills, and livestock so William could extract maximum gelds and feudal knight service."
          },
          {
            "misconception": "After winning the Battle of Hastings in October 1066, Anglo-Saxon resistance ended immediately.",
            "correction": "Major rebellions erupted for five years, peaking in 1069 when northern rebels and Danes wiped out the Norman garrison at York—provoking William's scorched-earth Harrying of the North (Source C)."
          }
        ],
        "send_adaptation": "Pre-teach motte-and-bailey (raised earth mound and timber courtyard fort) and Harrying (scorched-earth destruction of crops and villages). Chunk the Verso 5-Stage Spine into three concrete symbols—'Sword/Castle' (Stages 1 & 3), 'Fire' (Stage 2), and 'Book/Tax' (Stages 4 & 5)—before pupils complete the Two Key Features task.",
        "stretch_challenge": "Ask higher-attaining pupils to compare violent conquest with bureaucratic conquest: why was the 1086 Domesday survey of manors like Fareham (Source D) ultimately more permanent in destroying Anglo-Saxon power than the 1069 Harrying of the North?",
        "safeguarding_impartiality": "Handle Orderic Vitalis and the Peterborough Chronicle accounts of the 1069–70 Harrying of the North (100,000 famine deaths) with sober historical gravity rather than sensationalism, framing scorched-earth famine as deliberate medieval state terror examined through monastic primary evidence."
