                "summary": "After rebels entered London, burned hated tax records, and met 14-year-old King Richard II at Mile End, a tense second meeting took place at Smithfield on 15 June 1381. London’s Mayor stabbed Wat Tyler and Richard II later broke his charters of freedom—yet lords dared not pass another Poll Tax, and serfdom steadily crumbled across England.",
                "body": "After rebels entered London, burned hated tax records, and met 14-year-old King Richard II at Mile End, a tense second meeting took place at Smithfield on 15 June 1381. London’s Mayor stabbed Wat Tyler and Richard II later broke his charters of freedom—yet lords dared not pass another Poll Tax, and serfdom steadily crumbled across England.",
                "details": "After rebels entered London, burned hated tax records, and met 14-year-old King Richard II at Mile End, a tense second meeting took place at Smithfield on 15 June 1381. London’s Mayor stabbed Wat Tyler and Richard II later broke his charters of freedom—yet lords dared not pass another Poll Tax, and serfdom steadily crumbled across England.",
                "hinge": "Was the 1381 Peasants’ Revolt a failure because Wat Tyler was killed, or a long-term victory because serfdom and the Poll Tax withered away?"
