        "hinge_guidance": "Look for pupils tracing long-term frustration colliding with a sharp political trigger: after the 1348–50 plague halved the workforce, lords used the 1351 Statute of Labourers (Source B) and 1363 Sumptuary Laws to freeze wages and brand runaway serfs, building thirty years of resentment that finally ignited when John Bampton tried to enforce the flat 12-pence third Poll Tax at Brentwood in May 1381. Probe pupils who jump straight from plague deaths to Wat Tyler marching on London without explaining wage caps and Poll Taxes.",
